    solution: "WITH lagged AS (SELECT customer_id, order_date, LAG(order_date) OVER (PARTITION BY customer_id ORDER BY order_date) AS prev_date FROM orders), streaks AS (SELECT customer_id, order_date, SUM(CASE WHEN prev_date IS NULL OR julianday(order_date) - julianday(prev_date) > 7 THEN 1 ELSE 0 END) OVER (PARTITION BY customer_id ORDER BY order_date) AS streak_id FROM lagged) SELECT customer_id, MIN(order_date) AS streak_start, MAX(order_date) AS streak_end, COUNT(*) AS streak_length FROM streaks GROUP BY customer_id, streak_id HAVING COUNT(*) >= 3 ORDER BY streak_length DESC, customer_id",
