    solution: "SELECT DISTINCT o1.customer_id, o1.order_date AS first_order_date, o2.order_date AS next_order_date, o1.product AS first_order_product, o2.product AS next_order_product FROM orders o1 JOIN orders o2 ON o1.customer_id = o2.customer_id AND CAST(julianday(o2.order_date) - julianday(o1.order_date) AS INT) BETWEEN 1 AND 7 ORDER BY o1.customer_id, o1.order_date",
